\documentclass{article}
\usepackage{pgfplots}
\usepackage{hyperref}
\usepackage{graphicx}
\usepackage{amsmath}
\usepackage{cancel}
%% For tabular environment
\usepackage[T1]{fontenc}
\usepackage{makecell}
\usetikzlibrary{calc} 
\usepackage{tkz-euclide}
\usetkzobj{all}


\begin{document}
\pagestyle{empty}
\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}


\begin{tikzpicture}[scale=2.0] 

    \def\xmin{-2.0};
    \def\xmax{2.0};
    \def\ymin{-2.0};
    \def\ymax{2.0};
    \def\step{1};
    \def\acolor{orangepeel}    
    \def\pcolor{black}
	\def\psize{3}
	\def\lcolor{deepskyblue}
	\def\vcolor{red}   
	\def\r{1}; % Define the radius of the circle
	\def\rotationAngle{31} % Define the rotation angle


% Define some points that lie on the circle 
\tkzDefPoints{0/0/O, 1/0/XX, -1/0/xx, 0/1/YY, 0/-1/yy}

% Define some points that lie on the grid extremes of the grid
\tkzDefPoints{\xmin/0/X, \xmax/0/x, 0/\ymin/Y, 0/\ymax/y}



% Angles
\tkzDefPointBy[rotation = center O angle \rotationAngle](XX) \tkzGetPoint{P}

\tkzMarkAngle[draw=none, fill=\acolor, size=0.4](x,O,P); 
\tkzLabelAngle[pos=0.5](x,O,P){$\theta$};

%Draw Segment
\tkzDrawSegment[very thick, color=\pcolor](O,P)


%\pgfmathsetmacro{\k}{\r};


\tkzDrawCircle[R, very thick,color=\lcolor](O, \r cm) 

\tkzLabelPoints[right, yshift=3pt](P)
\tkzDrawPoints[color=none, fill=\pcolor, size=\psize](P)



%% Draw the grid
\draw[step=\step,black!30,very thin] (\xmin,\ymin) grid (\xmax,\ymax);
\tkzDrawVectors[style=thick](Y,y X,x)
\tkzLabelPoints[below right](x)
\tkzLabelPoints[above right](y)
\node[below right] at (XX){\small$1$};
\node[below left] at (xx){\small$-1$};
\node[above left] at (YY){\small$1$};
\node[below left] at (yy){\small$-1$};



\end{tikzpicture}
\end{document}

